#!/usr/bin/env -S uv run --script
# /// script
# requires-python = ">=3.11"
# dependencies = []
# ///
"""Rebuild the top-level `skills/` tree from its canonical sources.

`skills/` is a pure build artifact: it is deleted wholesale and recreated on
every run, so any dangling directory left behind by an earlier layout (including
entries that do not match `speckit-*`) is destroyed rather than preserved.

Canonical sources:
  * `assets/skills/init`                  -- the hand-authored init skill
  * `assets/bash/.claude/skills/speckit-*` -- generated by the asset-update
    workflow (`specify init --script sh`)

The rebuilt copies are what Claude Code discovers as plugin skills and what the
vercel-labs `skills` CLI installs, so `skills/` stays git-committed. "Build
artifact" means deterministically regeneratable, not untracked.

Usage:
    uv run scripts/build_skills.py
    uv run scripts/build_skills.py --root /path/to/checkout

Exits non-zero when either canonical source is missing or when the rebuilt tree
would contain zero skills, so a CI step can never silently produce an empty
`skills/`.
"""

from __future__ import annotations

import argparse
import os
import shutil
import stat
import sys
from pathlib import Path

INIT_SOURCE_REL = Path("assets") / "skills" / "init"
GENERATED_SOURCE_REL = Path("assets") / "bash" / ".claude" / "skills"
BUNDLE_REL = Path("skills")
PREFIX = "speckit-"
INIT_NAME = "init"


def generated_skills(parent: Path) -> list[Path]:
    """Return the `speckit-*` skill directories under `parent`, name-sorted."""
    if not parent.is_dir():
        return []
    return sorted(
        (child for child in parent.iterdir() if child.is_dir() and child.name.startswith(PREFIX)),
        key=lambda path: path.name,
    )


def make_scripts_executable(root: Path) -> int:
    """Add the executable bits to every `*.sh` under `root`. Returns the count."""
    count = 0
    for script in sorted(root.rglob("*.sh")):
        if not script.is_file():
            continue
        mode = script.stat().st_mode
        os.chmod(script, mode | stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH)
        count += 1
    return count


def rel_files(root: Path) -> dict[str, Path]:
    files: dict[str, Path] = {}
    if not root.is_dir():
        return files
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames.sort()
        filenames.sort()
        for name in filenames:
            path = Path(dirpath) / name
            files[path.relative_to(root).as_posix()] = path
    return files


def trees_byte_identical(src: Path, dst: Path) -> bool:
    """True when `dst` has the same relative files and bytes as `src`."""
    src_files = rel_files(src)
    dst_files = rel_files(dst)
    if set(src_files) != set(dst_files):
        return False
    return all(
        src_files[rel].read_bytes() == dst_files[rel].read_bytes() for rel in src_files
    )


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument(
        "--root",
        type=Path,
        default=Path(__file__).resolve().parent.parent,
        help="repository checkout to rebuild (default: this script's repository)",
    )
    args = parser.parse_args(argv)
    root = args.root.resolve()

    init_source = root / INIT_SOURCE_REL
    generated_source = root / GENERATED_SOURCE_REL
    bundle = root / BUNDLE_REL

    errors: list[str] = []
    if not init_source.is_dir():
        errors.append(f"missing authored init source: {INIT_SOURCE_REL.as_posix()}")
    if not generated_source.is_dir():
        errors.append(f"missing generated skill source: {GENERATED_SOURCE_REL.as_posix()}")
    if errors:
        print("error: cannot rebuild skills/:", file=sys.stderr)
        for message in errors:
            print(f"  - {message}", file=sys.stderr)
        return 1

    sources = generated_skills(generated_source)
    if not sources:
        print(
            f"error: no {PREFIX}* directories under {GENERATED_SOURCE_REL.as_posix()}; "
            "refusing to rebuild skills/ into an empty tree",
            file=sys.stderr,
        )
        return 1

    init_bundle = bundle / INIT_NAME
    if init_bundle.is_dir() and not trees_byte_identical(init_source, init_bundle):
        print(
            "warning: skills/init has local edits that will be discarded; "
            "edit the source assets/skills/init/ and rerun scripts/build_skills.py",
            file=sys.stderr,
        )

    # Wholesale wipe: this is what destroys dangling entries.
    shutil.rmtree(bundle, ignore_errors=True)
    bundle.mkdir(parents=True)

    shutil.copytree(init_source, bundle / INIT_NAME)
    for source in sources:
        shutil.copytree(source, bundle / source.name)

    built = sorted(child.name for child in bundle.iterdir() if child.is_dir())
    if not built:
        print("error: rebuilt skills/ is empty", file=sys.stderr)
        return 1

    scripts = make_scripts_executable(bundle)

    print(
        f"Rebuilt {BUNDLE_REL.as_posix()}/: {len(built)} skills "
        f"(1 authored from {INIT_SOURCE_REL.as_posix()}, "
        f"{len(sources)} generated from {GENERATED_SOURCE_REL.as_posix()}); "
        f"{scripts} *.sh marked executable"
    )
    for name in built:
        print(f"  - {name}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
